import React, { useEffect, useState } from "react";
import axios from "axios";
import { useParams, useNavigate } from "react-router-dom";

export default function EditDriverForm() {
  const { id } = useParams();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    licenseNumber: "",
  });

  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (id) {
      axios
        .get(`http://localhost:5000/api/drivers/${id}`)
        .then((res) => {
          console.log("Driver fetched:", res.data); // Debug output
          const { name, email, phone, licenseNumber } = res.data;
          setForm({ name, email, phone, licenseNumber });
          setLoading(false);
        })
        .catch((err) => {
          console.error("Fetch error:", err);
          setMessage("❌ Failed to load driver");
          setLoading(false);
        });
    }
  }, [id]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await axios.put(`http://localhost:5000/api/drivers/${id}`, form);
      setMessage("✅ Driver updated successfully!");
      setTimeout(() => navigate("/drivers"), 1000);
    } catch (err) {
      console.error("Update error:", err);
      setMessage("❌ Failed to update driver");
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ padding: "20px", maxWidth: "400px", margin: "auto" }}>
      <h2>Edit Driver</h2>

      {loading ? (
        <p>Loading...</p>
      ) : (
        <>
          {["name", "email", "phone", "licenseNumber"].map((field) => (
            <input
              key={field}
              name={field}
              placeholder={field}
              value={(form as any)[field]}
              onChange={handleChange}
              required
              style={{ marginBottom: "10px", width: "100%", padding: "8px" }}
            />
          ))}
          <div>
            <button type="submit" style={{ padding: "10px 20px", marginRight: "10px" }}>
              Update
            </button>
            <button
              type="button"
              style={{
                padding: "10px 20px",
                backgroundColor: "#6c757d",
                color: "#fff",
                border: "none",
                borderRadius: "4px",
              }}
              onClick={() => navigate("/drivers")}
            >
              ← Back to Driver List
            </button>
          </div>
          {message && (
            <p style={{ color: message.includes("✅") ? "green" : "red", marginTop: "10px" }}>
              {message}
            </p>
          )}
        </>
      )}
    </form>
  );
}
